mapper.select:
SELECT a.model_name FROM three_dimensional_relevancy a
WHERE 1 = 1
and a.name = #{deviceName,jdbcType=VARCHAR}
and a.device_type = #{deviceType,jdbcType=INTEGER}

SELECT id from three_dimensional_relevancy
where 1 = 1
and model_name = #{modelName,jdbcType=VARCHAR}

SELECT b.preset_id AS cruise_id, a.camera_id, a.record_id, a.camera_name, b.preset_name FROM t_camera_info a, t_camera_preset b WHERE a.camera_id = b.camera_id
AND b.preset_id IN ( SELECT tcp.preset_id FROM t_cruise_point_instance tcpi LEFT JOIN t_camera_preset tcp ON tcpi.cruise_id = tcp.preset_id WHERE tcpi.device_mete_id = #{modelName, jdbcType = VARCHAR} )
AND a.camera_name = #{cameraName, jdbcType= VARCHAR}
